def cl(x):
 if isinstance(x,str):return x.replace('加工','প্রক্রিয়াকরণ').replace('担当','দায়িত্বপ্রাপ্ত ')
 if isinstance(x,(list,tuple)):return[cl(a)for a in x]
 return x
